import{useEffect,useRef,useState}from'react';
export function roveIndex(key,current,count,opts={}){
if(count<=0)
return null;
const{orientation='vertical',loop=true}=opts;
const prev=(orientation==='vertical'&&key==='ArrowUp')||(orientation==='horizontal'&&key==='ArrowLeft')||(orientation==='both'&&(key==='ArrowUp'||key==='ArrowLeft'));
const next=(orientation==='vertical'&&key==='ArrowDown')||(orientation==='horizontal'&&key==='ArrowRight')||(orientation==='both'&&(key==='ArrowDown'||key==='ArrowRight'));
if(key==='Home')
return 0;
if(key==='End')
return count-1;
if(!prev&&!next)
return null;
if(current<0)
return prev?count-1:0;
const to=current+(next?1:-1);
if(to<0)
return loop?count-1:0;
if(to>=count)
return loop?0:count-1;
return to;
}
export function enabledIn(container,selector){
if(!container)
return[];
return[...container.querySelectorAll(selector)].filter((el)=>!el.hasAttribute('disabled')&&el.getAttribute('aria-disabled')!=='true');
}
export function roveFocus(event,container,selector,opts){
const items=enabledIn(container,selector);
const active=typeof document==='undefined'?null:document.activeElement;
const to=roveIndex(event.key,active?items.findIndex((el)=>el===active||el.contains(active)):-1,items.length,opts);
if(to===null)
return false;
event.preventDefault();
items[to]?.focus();
if(opts?.activate)
items[to]?.click();
return true;
}
export function useDismiss(open,onDismiss,inside,opts={}){
const latest=useRef({onDismiss,inside});
latest.current={onDismiss,inside};
const{escape=true,outside=true}=opts;
useEffect(()=>{
if(!open)
return;
const onKey=(e)=>{
if(e.key==='Escape'&&!e.defaultPrevented)
latest.current.onDismiss('escape');
};
const onPress=(e)=>{
const target=e.target;
if(!target)
return;
if(latest.current.inside.some((ref)=>ref.current?.contains(target)))
return;
latest.current.onDismiss('outside');
};
if(escape)
document.addEventListener('keydown',onKey);
if(outside)
document.addEventListener('pointerdown',onPress);
return()=>{
document.removeEventListener('keydown',onKey);
document.removeEventListener('pointerdown',onPress);
};
},[open,escape,outside]);
}
const TABBABLE='a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
export function useModalFocus(active,ref){
useEffect(()=>{
const el=ref.current;
if(!active||!el)
return;
const previous=document.activeElement;
if(!el.contains(previous))
(enabledIn(el,TABBABLE)[0]??el).focus({preventScroll:true});
return()=>{
if(previous?.isConnected)
previous.focus({preventScroll:true});
};
},[active,ref]);
return(event)=>{
if(event.key!=='Tab')
return;
const el=ref.current;
if(!el)
return;
const items=enabledIn(el,TABBABLE);
if(items.length===0){
event.preventDefault();
el.focus();
return;
}
const first=items[0];
const last=items[items.length-1];
const at=document.activeElement;
if(event.shiftKey&&(at===first||at===el)){
event.preventDefault();
last.focus();
}
else if(!event.shiftKey&&at===last){
event.preventDefault();
first.focus();
}
};
}
export function useDismissibleHint(){
const[hovered,setHovered]=useState(false);
const[focused,setFocused]=useState(false);
const[dismissed,setDismissed]=useState(false);
const active=hovered||focused;
useEffect(()=>{
if(!active)
setDismissed(false);
},[active]);
useDismiss(active&&!dismissed,()=>setDismissed(true),[],{outside:false});
return{
dismissed,
handlers:{
onMouseEnter:()=>setHovered(true),
onMouseLeave:()=>setHovered(false),
onFocus:()=>setFocused(true),
onBlur:()=>setFocused(false),
},
};
}
